import type { BrainAssetMapping, ContextMeshMapping, Vec3 } from "./types";

/**
 * Central mapping between content regions and public/models/brain.glb.
 * Marker anchors were generated by scripts/asset-pipeline/build_brain_mesh.py
 * (see anchors.generated.json). Model frame: x = subject right, y = superior,
 * z = posterior (anterior is -z); 1 unit = 100 mm.
 *
 * Mesh names alone do not establish anatomical accuracy: groupings were defined from
 * CerebrA atlas labels and visually checked against the atlas orientation.
 */
